package com.myassist.assistant.ui;
import android.os.Bundle;import android.view.View;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.myassist.assistant.MyAssistApp;import com.myassist.assistant.model.Models;import com.myassist.assistant.network.*;import org.json.JSONObject;
public class JobDetailsActivity extends AppCompatActivity{int id;Models.ServiceRequest current;TextView status,body,error;Button action;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_job_details);id=getIntent().getIntExtra("request_id",-1);status=findViewById(R.id.tvStatus);body=findViewById(R.id.tvBody);error=findViewById(R.id.tvError);action=findViewById(R.id.btnAction);action.setOnClickListener(v->act());load();}void load(){ApiService.run(ApiService.get("api/v1/assistant/jobs/"+id),Models.ServiceRequest::fromJson,new ApiService.Callback<Models.ServiceRequest>(){public void onSuccess(Models.ServiceRequest r){current=r;runOnUiThread(()->render());}public void onError(ApiClient.ApiException e){runOnUiThread(()->error.setText(e.userMessage));}});}void render(){status.setText(current.status);body.setText("Job #"+current.id+"\nService: "+current.serviceType+"\n\n"+current.description+"\n\nPickup: "+current.pickupAddress+" ("+current.pickupLat+", "+current.pickupLng+")\nDestination: "+current.destinationAddress+" ("+current.destLat+", "+current.destLng+")");boolean mine=current.assistantId!=null&&current.assistantId==MyAssistApp.session().userId();if("PENDING".equals(current.status)){action.setText("ACCEPT JOB");action.setVisibility(View.VISIBLE);}else if("ACCEPTED".equals(current.status)&&mine){action.setText("MARK COMPLETED");action.setVisibility(View.VISIBLE);}else action.setVisibility(View.GONE);}void act(){if(current==null)return;String path="api/v1/assistant/jobs/"+id+("PENDING".equals(current.status)?"/accept":"/complete");ApiService.run(ApiService.post(path,new JSONObject()),x->x,new ApiService.Callback<JSONObject>(){public void onSuccess(JSONObject x){load();}public void onError(ApiClient.ApiException e){runOnUiThread(()->error.setText(e.userMessage));load();}});}}